import { atom, read, update } from 'claude-code'
import type { CoreEngineInterface, Register, Timer } from 'claude-code'

import { dots } from './dots.ts'
import { dark, painter } from './painter.ts'
import * as pieces from './vendor/pieces/index.ts'
import type { Frame, Piece } from './vendor/types.ts'

const ART = 'art'
// Raster's colour for "the terminal's own"
const DEFAULT = 0x01000000
// ponytail: 3 px a dot, 600 x 300 and a 12 to 25 KB PNG a frame for a 200 x 100 scene; raise it for a sharper picture if frames keep up
const SCALE = 3

const playing = atom({ plugin: 'ascii-rest', key: 'playing' } as const, null)
const picking = atom({ plugin: 'ascii-rest', key: 'picking' } as const, null)

type Cells = ReturnType<typeof painter>
// A scene plays as an Image of its dots, any other piece as a Raster of its characters.
type Art = { pic: ReturnType<typeof dots>; color: Uint8Array } | { cells: Cells }
// Its own timer, so a tick left over from the last piece can only end itself.
type Player = { name: string; frame: Frame; paper: boolean; fps: number; start: number; art: Art; w: number; h: number; tick?: Timer; busy: boolean; denied: number }

// "nightCoast" -> "night-coast", the names ascii.rest's site and CLI use
export const byName = new Map(
  Object.entries(pieces).map(([key, piece]) => [key.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`), piece as Piece]),
)

/** The middle `w` x `h` of the painted cells, cropped or padded with the ground, as Raster's base64 `[codePoint, fg, bg]` u32 triplets. */
export function encode(cells: Cells, w: number, h: number): string {
  const words = new Uint32Array(w * h * 3)
  const ground = cells.base < 0 ? DEFAULT : cells.base
  const sx = (cells.cols - w) >> 1, sy = (cells.rows - h) >> 1
  for (let y = 0, k = 0; y < h; y++)
    for (let x = 0; x < w; x++, k += 3) {
      const cx = sx + x, cy = sy + y
      if (cx < 0 || cx >= cells.cols || cy < 0 || cy >= cells.rows) {
        words[k] = 32
        words[k + 1] = DEFAULT
        words[k + 2] = ground
        continue
      }
      const i = cy * cells.cols + cx
      words[k] = cells.ch[i].charCodeAt(0)
      words[k + 1] = cells.fg[i] < 0 ? DEFAULT : cells.fg[i]
      words[k + 2] = cells.bg[i] < 0 ? DEFAULT : cells.bg[i]
    }
  return new Uint8Array(words.buffer).toBase64()
}

// category -> its pieces' names, in ascii.rest's order
const groups = new Map<string, string[]>()
for (const [name, { meta }] of byName) groups.set(meta.category, [...(groups.get(meta.category) ?? []), name])
const list = () => [...groups].map(([category, names]) => `${category}: ${names.join(', ')}`).join('\n')
const names = [...byName.keys()]
const random = () => names[Math.floor(Math.random() * names.length)]

// The band reads both and draws again on a write; a drawn picker stops the piece, so neither has to.
async function play($: Pick<CoreEngineInterface, 'state' | 'ui'>, name: string) {
  await update($, picking, () => null)
  await update($, playing, () => name)
  $.ui.invalidate('ui.render')
}
function pick($: Pick<CoreEngineInterface, 'state'>, category: string) {
  return update($, picking, () => category)
}

export const register: Register = on => {
  // Module variables: a reload starts them over, and the next draw of the band starts the piece again.
  let player: Player | undefined
  // A scene is a picture until the engine says this terminal draws none (herdr, tmux), then half blocks.
  let pictures = true

  // Time from the clock, not counted in ticks: a late tick skips a frame instead of slowing the piece down.
  const paint = (p: Player, now: number) => {
    const t = (now - p.start) / 1000
    if ('pic' in p.art) p.art.pic.paint(p.frame(t, { paper: p.paper, color: p.art.color }), p.art.color)
    else p.art.cells.paint(p.frame(t, { paper: p.paper, color: p.art.cells.color }))
  }
  const stop = () => {
    player?.tick?.cancel()
    player = undefined
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'ascii',
      description: 'Play an ascii.rest animation above the prompt: /ascii [piece | random | list | stop], a picker when empty',
    })

    return next(e)
  })

  on('command.run', { command: 'ascii' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'list') return { text: list() }
    if (!arg) {
      await pick($, byName.get(player?.name ?? '')?.meta.category ?? 'scenes')
      return { text: 'Pick a piece above the prompt.' }
    }

    stop()
    if (arg === 'stop') {
      await update($, picking, () => null)
      await update($, playing, () => null)
      return { text: 'Stopped.' }
    }

    const name = arg === 'random' ? random() : arg
    if (!byName.has(name)) return { text: `No piece "${name}". /ascii list shows all ${names.length}.` }

    await play($, name)

    return { text: `Playing ${name} above the prompt; /ascii stop hides it.` }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const elements = $.ui.resolve(e)
    // Raster and Image are the terminal's alone
    if (!('Raster' in elements)) return next(e)
    const { Box, Button, Image, Raster, Text } = elements

    const shown = await read($, picking)
    if (shown !== null) {
      stop()
      return (
        <Box flexDirection="column" rowGap={1}>
          <Box flexWrap="wrap" columnGap={2}>
            {[...groups.keys()].map(c => (
              <Button key={`cat:${c}`} label={c} plain dimColor={c !== shown} onPress={() => pick($, c)} />
            ))}
          </Box>
          <Box flexWrap="wrap" columnGap={2}>
            {(groups.get(shown) ?? []).map(n => (
              <Button key={`piece:${n}`} label={n} plain onPress={() => play($, n)} />
            ))}
          </Box>
          <Box columnGap={2}>
            <Button key="random" label="random" onPress={() => play($, random())} />
            <Button key="stop" label="stop" onPress={() => update($, picking, () => null).then(() => update($, playing, () => null))} />
          </Box>
        </Box>
      )
    }

    const name = await read($, playing)
    const piece = name === null ? undefined : byName.get(name)
    if (name === null || !piece) return next(e)

    const { meta } = piece
    if (player?.name !== name) {
      const art: Art =
        pictures && meta.cell === 1 && meta.palette && meta.ground
          ? { pic: dots(meta, SCALE), color: new Uint8Array(meta.cols * meta.rows) }
          : { cells: painter(meta, true) }
      // A piece keeps its own ground and shades for it; anything else assumes a dark terminal.
      const base = 'pic' in art ? art.pic.base : art.cells.base
      const start = await $.clock.now()
      player = { name, frame: piece.default({ ...meta.options }), paper: base >= 0 ? !dark(base) : false, fps: meta.fps, start, art, w: 0, h: 0, busy: false, denied: 0 }
    }
    const p = player
    const art = p.art
    // The band's width, at most half the screen (outside fullscreen maxRows is all of it), less the caption's row.
    const W = Math.min(255, e.props.bodyColumns)
    const H = Math.max(1, Math.min(e.props.maxRows, Math.floor((e.viewport?.rows ?? 48) / 2)) - 1)
    if ('pic' in art) {
      // a terminal cell is about twice as tall as it is wide
      p.w = Math.max(1, Math.min(W, Math.floor((2 * H * meta.cols) / meta.rows)))
      p.h = Math.max(1, Math.round((p.w * meta.rows) / meta.cols / 2))
    } else {
      art.cells.size(W, H)
      // as wide as the piece, so the Box centres it rather than its ground filling the band either side
      p.w = Math.min(W, art.cells.cols)
      p.h = Math.min(art.cells.rows, H)
    }
    paint(p, await $.clock.now())

    const site = e.requestId
    if (p.fps > 0 && !p.tick) {
      const tick = $.clock.every(Math.round(1000 / p.fps), async () => {
        if (player !== p) return tick.cancel()
        // The last frame still on its way: skip this tick rather than queue behind it.
        if (p.busy) return
        p.busy = true
        try {
          paint(p, await $.clock.now())
          // the engine refuses with { deny }; a hook above refusing rejects
          const { deny } = await $.ui
            .blit(
              'pic' in art
                ? { requestId: site, key: ART, source: art.pic.source() }
                : { requestId: site, key: ART, columns: p.w, rows: p.h, cells: encode(art.cells, p.w, p.h) },
            )
            .catch((err: unknown) => ({ deny: String(err) }))
          // The one redraw from here: its tree holds no Image, so it cannot be refused this way again.
          if ('pic' in art && deny?.includes('draws its alt')) {
            pictures = false
            stop()
            return $.ui.invalidate('ui.render')
          }
          // A refusal or two is a resize landing; a second of them (the band hidden, an Image showing its alt) rests
          // the piece until the band draws again. Never a redraw from here: one that is refused again loops.
          p.denied = deny ? p.denied + 1 : 0
          if (p.denied > p.fps) {
            tick.cancel()
            p.tick = undefined
          }
        } finally {
          p.busy = false
        }
      })
      p.tick = tick
    }

    return (
      <Box flexDirection="column" alignItems="center">
        {'pic' in art ? (
          <Image key={ART} source={art.pic.source()} columns={p.w} rows={p.h} alt={name} />
        ) : (
          <Raster key={ART} columns={p.w} rows={p.h} cells={encode(art.cells, p.w, p.h)} />
        )}
        <Box columnGap={2}>
          <Text dimColor wrap="truncate">
            {name}: {meta.note}
          </Text>
          <Button key="pick" label="pick another" plain dimColor onPress={() => pick($, meta.category)} />
        </Box>
      </Box>
    )
  })
}

