import { png } from './png.ts'
import type { Meta } from './vendor/types.ts'

// Each dot's diameter as a share of its square cell: the glyph's size in SF Mono (ui-monospace on a Mac), drawn at 1/0.6
// of the cell as ascii.rest's canvas draws it, measured with Pillow. The knob to tune the look.
const DOT: Record<string, number> = { '·': 0.22, '•': 0.67, '●': 1.03 }
// samples a pixel takes each way, for a dot's soft edge
const SAMPLES = 4

/** A scene's frames as RGBA pixels, `scale` a cell: each dot a disc of its palette ink on the ground, as the site draws it. */
export function dots({ cols, rows, palette = [], ground = '#000000' }: Meta, scale: number) {
  const width = cols * scale, height = rows * scale
  const rgba = new Uint8Array(width * height * 4)
  const rgb = (hex: string) => parseInt(hex.slice(1, 7), 16)
  const base = rgb(ground), inks = palette.map(rgb)
  // the ground as one little-endian RGBA word
  const fill = (0xff000000 | ((base & 255) << 16) | (base & 0xff00) | (base >> 16)) >>> 0
  // how much of each of a cell's pixels a dot covers
  const masks = new Map(
    Object.entries(DOT).map(([c, d]) => {
      const mask = new Float32Array(scale * scale), r = (d * scale) / 2, mid = scale / 2
      for (let j = 0; j < scale; j++)
        for (let i = 0; i < scale; i++) {
          let n = 0
          for (let v = 0; v < SAMPLES; v++)
            for (let u = 0; u < SAMPLES; u++) if (Math.hypot(i + (u + 0.5) / SAMPLES - mid, j + (v + 0.5) / SAMPLES - mid) <= r) n++
          mask[j * scale + i] = n / SAMPLES ** 2
        }
      return [c, mask]
    }),
  )

  const paint = (text: string, color: Uint8Array) => {
    new Uint32Array(rgba.buffer).fill(fill)
    const lines = text.split('\n')
    for (let y = 0; y < rows; y++)
      for (let x = 0; x < cols; x++) {
        const c = lines[y]?.[x]
        if (c === undefined || c === ' ') continue
        const mask = masks.get(c) ?? masks.get('•')!
        const ink = inks[color[y * cols + x]] ?? inks[0] ?? 0xffffff
        const r = ink >> 16, g = (ink >> 8) & 255, b = ink & 255
        for (let j = 0; j < scale; j++)
          for (let i = 0, k = ((y * scale + j) * width + x * scale) * 4; i < scale; i++, k += 4) {
            const a = mask[j * scale + i]
            if (a === 0) continue
            rgba[k] += (r - rgba[k]) * a
            rgba[k + 1] += (g - rgba[k + 1]) * a
            rgba[k + 2] += (b - rgba[k + 2]) * a
          }
      }
  }
  // as a PNG, a 30th of the raw pixels; raw past 256 colours
  const source = () => {
    const file = png(rgba, width, height)
    return file ? { png: file.toBase64() } : { rgba: rgba.toBase64(), width, height }
  }
  return { width, height, base, rgba, paint, source }
}

