  name: "almalinux",
  category: "distros",
  note: "five coloured figures in a ring, scanned now and then",
  cols: 56,
  rows: 28,
  fps: 30,
  options: { scan: 5 },
  // The logo's 5 colours for a light page, then for a dark one; each as drawn, then twice lighter for the scan.
