        FG[k] = cg;
        FB[k] = cb;
        floor[k] = 0.26;
        fade[k] = smooth(H + 2, H - 22, y);
        if (r === SHORE) {
          // a dark seam where the shore meets the water
          FR[k] = 0.06;
          FG[k] = 0.12;
          FB[k] = 0.14;
          floor[k] = 0;
        }
      }
    }

    // the near pines and the bank, black against it all, rimmed on the sun side
    for (let k = 0; k < N; k++) {
      if (!fg[k]) continue;
      const s = fgShade[k];
      FR[k] = 0.02 + 0.05 * s;
      FG[k] = 0.04 + 0.06 * s;
      FB[k] = 0.05 + 0.06 * s;
      floor[k] = 0;
      const e = fgRim[k];
