        const lean = Math.cos(0.9 * s - smoke * 3);
        out[r * cols + Math.floor(x)] = age > 1.4 ? "." : lean > 0.5 ? ")" : lean < -0.5 ? "(" : "|";
      }
    return Array.from({ length: rows }, (_, r) => out.slice(r * cols, (r + 1) * cols).join("")).join("\n");
  };
}

