  [[9, 2, ".-."], [10, 1, "( ,'"], [11, 2, "\\ `."], [12, 3, "`."], [13, 5, "`-.__"]],
  [[7, 2, ".-."], [8, 1, "/ ,'"], [9, 1, "| |"], [10, 1, "\\ \\"], [11, 2, "\\ `."], [12, 3, "`."], [13, 5, "`-.__"]],
