        const c = Math.floor(x), r = Math.floor(y);
        if (r >= rows || c >= cols) continue;
        if (!inside(r, c) || g[r][c] !== " ") continue;
        g[r][c] = TUMBLE[Math.floor(age * p.spin + p.ph) % TUMBLE.length];
      }
    }
    return g.map((row) => row.join("")).join("\n");
  };
}

