      let row = "│";
      for (let c = 0; c < IC; c++) {
        const i = r * IC + c, q = all[i];
        row += (landed[i] && is[i]) || (lying[i] && was[i]) || (q === 0 ? " " : q < 3 ? "·" : ":");
      }
      lines.push(row + "│");
    }
    lines.push("└" + "─".repeat(IC) + "┘");
    return lines.join("\n");
  };
}

