  const dith = new Float32Array(N);
  const floor0 = new Float32Array(N);
  for (let r = 0; r < H; r++) {
    for (let x = 0; x < W; x++) {
      const k = r * W + x;
      const bay = BAYER[(r & 3) * 4 + (x & 3)];
      if (mat[k] === SKY) {
