  const stars: [number, number, number[], number, number][] = [];
  for (let r = 0; r < HZ + 2; r++) {
    for (let x = 0; x < W; x++) {
      const k = r * W + x;
      if (mat[k] !== SKY) continue;
      const p = 0.015 + 0.12 * clamp(band[k]);
      if (hash(x * 7 + 3, r * 13 + 1) > p) continue;
