      for (let x = 0; x < W; x++) {
        const k = r * W + x;
        if (mat[k] !== SKY) continue;
        const a = air[k] * (0.86 + 0.28 * noise((x - t * 0.3) * 0.03, r * 0.08));
        FR[k] += a * 0.3;
        FG[k] += a * 0.5;
        FB[k] += a * 1.2;
      }
    }
    for (let k = 0; k < N; k++) {
      const m = mat[k];
      if (m === SAND) {
        FR[k] = sR[k];
        FG[k] = sG[k];
        FB[k] = sB[k];
        const c = crest[k];
        if (c > 0) {
          // sand glinting along the brink of each slip face
          const h = hash(k, 5);
          const g = c * Math.pow(Math.max(0, Math.sin(t * (0.8 + 2.2 * h) + h * 40)), 8) * 0.5;
