          FG[k] += g * 0.85;
          FB[k] += g * 0.7;
        }
      } else if (m === TREE) {
        const e = bark[k];
        FR[k] = e * 0.42;
        FG[k] = e * 0.3;
        FB[k] = e * 0.2;
        floor[k] = e > 0 ? 0.1 : 0;
      }
    }
    for (const [k, b, tint, rate, ph] of stars) {
      const tw = b > 0.35 ? 0.72 + 0.28 * Math.sin(t * rate + ph) : 0.6 + 0.4 * Math.sin(t * rate + ph);
      const s = b * tw;
      FR[k] += s * tint[0];
      FG[k] += s * tint[1];
      FB[k] += s * tint[2];
      floor[k] = 0.28;
    }
    for (const [k, ph, rate] of lamps) {
      const g = 0.42 + 0.14 * Math.sin(t * rate + ph) * Math.sin(t * rate * 2.3 + ph * 3);
