      FG[k] = 0.85 * g;
      FB[k] = 0.66 * g;
      floor[k] = 0.12;
    }
    // a meteor, if one is crossing
    const n = Math.floor((t - 2.5) / 7) + 1;
    for (let i = Math.max(0, n - 1); i <= n + 1; i++) {
      const [start, x0, y0, dx, dy, speed] = meteor(i);
